taport1.apcd_airport_name_s AS apcdEAirportNames, CONCAT(taport.apcd_airport_name_s,'-',taport1.apcd_airport_name_s) AS flightValic from ( select t1.* from T_FLIGHT t1, ( select flgt_regn from T_FLIGHT where flgt_flop BETWEEN DATE_SUB(curdate(),INTERVAL 1 DAY) AND CURDATE() and flgt_regn <> '' and flgt_game = 'Y' and flgt_airport_code = #{staffAirportCode}
and flgt_aptarea_code = #{staffAptareaCode}
GROUP BY flgt_regn having count(1) > 1 )t2 where t1.flgt_regn = t2.flgt_regn and t1.flgt_adid = 'D' UNION select t3.* from T_FLIGHT t3, ( select flgt_regn from T_FLIGHT where flgt_flop = CURDATE() and flgt_game = 'Y' and flgt_regn <> '' and flgt_airport_code = #{staffAirportCode}
and flgt_aptarea_code = #{staffAptareaCode}
GROUP BY flgt_regn having count(1) = 1 )t4 where t4.flgt_regn = t3.flgt_regn) t5 LEFT JOIN T_AIRLINES_CODE tainscode ON tainscode.alcd_icao_code=t5.flgt_al2c LEFT JOIN T_AIRPORT_CODE taport ON taport.apcd_iata_code=t5.flgt_org3c LEFT JOIN T_AIRPORT_CODE taport1 ON taport1.apcd_iata_code=t5.flgt_des3c left join T_TASK task ON t5.flgt_id = task.task_flight_id ORDER BY t5.flgt_d_stot

