 AS taskFuelRecptNo, task.task_vehi_no AS taskVehiNo, task.task_cre_staff_id AS taskCreStaffId, task.task_starmark AS taskStarmark, task.task_rec_cre_time AS taskRecCreTime, CASE WHEN t7.flgt_rflno is not null THEN 1 ELSE 0 END AS flgtstatus from T_FLIGHT t5 LEFT JOIN T_TASK task ON t5.flgt_id=task.task_flight_id LEFT JOIN T_FLIGHT t6 ON t6.flgt_regn=t5.flgt_regn AND t6.flgt_flno=t5.flgt_link_flno AND t5.flgt_flop=t6.flgt_link_flop AND t5.flgt_repeat=t6.flgt_link_repeat LEFT JOIN T_FLIGHT_SUBSCRIPTION t7 ON t7.flgt_rflno=t5.flgt_flno AND t7.flgt_rflop =t5.flgt_flop where t5.flgt_flop = CURDATE()
