f2.flgt_org3c AS beorg3c, tf2.flgt_a_stot AS flgtAStot, tf2.flgt_a_etot AS flgtAEtot, tf2.flgt_a_atot AS flgtAAtot, tf2.flgt_placecode AS flgtPlacecodeIn, tf2.flgt_flti AS flgtFltiIn FROM T_TASK AS task, T_FLIGHT AS flight LEFT JOIN T_FLIGHT tf2 ON IF ( tf2.flgt_a_atot is not null, tf2.flgt_a_atot > DATE_ADD(CURDATE(),INTERVAL 0 HOUR), tf2.flgt_a_stot > DATE_ADD(CURDATE(),INTERVAL 0 HOUR) ) AND tf2.flgt_adid = 'A' AND flight.flgt_airport_code = tf2.flgt_airport_code AND ((flight.flgt_link_flno IS NOT NULL AND flight.flgt_link_flno <> '' AND tf2.flgt_flno LIKE CONCAT('%',flight.flgt_link_flno,'%'))) AND ((tf2.flgt_link_flno IS NOT NULL AND tf2.flgt_link_flno <> '' AND flight.flgt_flno LIKE CONCAT('%',tf2.flgt_link_flno,'%'))) AND flight.flgt_regn = tf2.flgt_regn AND flight.flgt_link_flop = tf2.flgt_flop AND flight.flgt_flop = tf2.flgt_link_flop AND flight.flgt_repeat = tf2.flgt_link_repeat AND flight.flgt_link_repeat = tf2.flgt_repeat WHERE task.task_flight_id = flight.flgt_id AND flight.flgt_ftyp <> 'NO' AND flight.flgt_ftyp <> 'CX'AND flight.flgt_ftyp <> 'DE' AND flight.flgt_adid = 'D' AND IF ( flight.flgt_d_etot is null, flight.flgt_d_stot >= DATE_ADD(#{date},INTERVAL 4 HOUR) AND flight.flgt_d_stot < DATE_ADD(#{date},INTERVAL 28 HOUR), flight.flgt_d_etot >= DATE_ADD(#{date},INTERVAL 4 HOUR) AND flight.flgt_d_etot < DATE_ADD(#{date},INTERVAL 28 HOUR) ) AND flight.flgt_airport_code = #{staffAirportCode}
