SELECT task.task_id AS taskId, task.task_ope_staff_id AS taskOpeStaffId, task.task_content AS taskContent, task.task_status AS taskStatus, task.task_asg_time AS taskAsgTime, task.task_acc_time AS taskAccTime, task.task_chag_sta_time AS taskChagStaTime, task.task_chag_end_time AS taskChagEndTime, task.task_done_time AS taskDoneTime, task.task_fuel_recpt_no AS taskFuelRecptNo, task.task_vehi_no AS taskVehiNo, task.task_cre_staff_id AS taskCreStaffId, task.task_starmark AS taskStarmark, task.task_rec_cre_time AS taskRecCreTime, flight.flgt_id AS flgtId, flight.flgt_ffid AS flgtFfid, flight.flgt_airport_code AS flgtAirportCode, flight.flgt_aptarea_code AS flgtAptareaCode, flight.flgt_flno AS flgtFlno, flight.flgt_flop AS flgtFlop, flight.flgt_acname AS flgtAcname, flight.flgt_regn AS flgtRegn, flight.flgt_placecode AS flgtPlacecode, flight.flgt_al2c AS flgtAl2c, flight.flgt_alcname AS flgtAlcname, flight.flgt_a_stot AS flgtAStot, flight.flgt_a_etot AS flgtAEtot, flight.flgt_a_atot AS flgtAAtot, flight.flgt_org3c AS flgtOrg3c, flight.flgt_orgnm AS flgtOrgnm, flight.flgt_trs3c1 AS flgtTrs3c1, flight.flgt_trs3c2 AS flgtTrs3c2, flight.flgt_trs3c3 AS flgtTrs3c3, flight.flgt_trs3c4 AS flgtTrs3c4, flight.flgt_trs3c5 AS flgtTrs3c5, flight.flgt_trsnm1 AS flgtTrsnm1, flight.flgt_trsnm2 AS flgtTrsnm2, flight.flgt_trsnm3 AS flgtTrsnm3, flight.flgt_trsnm4 AS flightValic, flight.flgt_trsnm5 AS flgtVialc, flight.flgt_des3c AS flgtDes3c, flight.flgt_desnm AS flgtDesnm, flight.flgt_adid AS flgtAdid, flight.flgt_flti AS flgtFlti, flight.flgt_ftyp AS flgtFtyp, flight.flgt_proxy AS flgtProxy, flight.flgt_fnflag AS flgtFnflag, flight.flgt_game AS flgtGame, flight.flgt_chocks_in AS flgtChocksIn, flight.flgt_chocks_out AS flgtChocksOut, flight.flgt_vip AS flgtVip, flight.flgt_num AS flgtNum, flight.flgt_otc AS flgtOtc, flight.flgt_repeat AS flgtRepeat, flight.flgt_link_flop AS flgtLinkFlop, flight.flgt_link_repeat AS flgtLinkRepeat, flight.flgt_otc AS flgtOtc, flight.flgt_link_flno AS flgtLinkFlno FROM T_FLIGHT flight LEFT JOIN T_TASK task ON task.task_flight_id = flight.flgt_id WHERE flight.flgt_ftyp <> 'NO' AND flight.flgt_ftyp <> 'CX' AND flight.flgt_adid = 'A' AND flight.flgt_a_stot IS NOT NULL AND flight.flgt_a_stot <> '' AND DATE_FORMAT(DATE_ADD(flight.flgt_a_stot,INTERVAL -4 HOUR),'%Y%m%d') = DATE_FORMAT(DATE_ADD(NOW(),INTERVAL -4 HOUR),'%Y%m%d') AND flight.flgt_airport_code = #{staffAirportCode}
